canon_clock.script:
const tick = check({type:'game-tick'});
if (storage.canon_start_tick === undefined) {
  const isAinz = check({type:'player-traits', operator:'contains', value:"Ainz's Regalia"});
  if (!isAinz) { storage.canon_start_tick = tick; }
  else if (check({type:'read-boolean', key:'nazarick_survey_init'})) { storage.canon_start_tick = tick; }
  else if (tick >= 60) { storage.canon_start_tick = tick; }
}
storage.canon_elapsed = (storage.canon_start_tick === undefined) ? -1 : (tick - storage.canon_start_tick);

