Standing Init.script:
if (storage.standing_reestize === undefined) {
  storage.standing_reestize    = 0;
  storage.standing_baharuth    = 0;
  storage.standing_theocracy   = 0;
  storage.standing_adventurers = 0;
  storage.standing_dwarf       = 0;
  storage.standing_karsanas    = 0;
  storage.threshold_reestize    = 'neutral';
  storage.threshold_baharuth    = 'neutral';
  storage.threshold_theocracy   = 'neutral';
  storage.threshold_adventurers = 'neutral';
  storage.threshold_dwarf       = 'neutral';
  storage.threshold_karsanas    = 'neutral';
}
  storage.as_momon = false;
delete triggers["Standing Init"];

Standing Monitor.script:
const band = (v) => {
  if (v >= 50)  return 'allied';
  if (v >= 10)  return 'cooperative';
  if (v >= -9)  return 'neutral';
  if (v >= -49) return 'hostile';
  return 'war';
};

const factions = [
  { standing: 'standing_reestize',    threshold: 'threshold_reestize',    name: 'Re-Estize Kingdom'  },
  { standing: 'standing_baharuth',    threshold: 'threshold_baharuth',    name: 'Baharuth Empire'    },
  { standing: 'standing_theocracy',   threshold: 'threshold_theocracy',   name: 'Slane Theocracy'    },
  { standing: 'standing_adventurers', threshold: 'threshold_adventurers', name: "Adventurers' Guild" },
  { standing: 'standing_dwarf',       threshold: 'threshold_dwarf',       name: 'Dwarf Kingdom'      },
  { standing: 'standing_karsanas',    threshold: 'threshold_karsanas',    name: 'Karsanas City State Alliance' }
];

const posture = {
  allied:      'has moved to open alliance — active cooperation and goodwill at all levels',
  cooperative: 'now maintains a cautiously cooperative stance',
  neutral:     'has settled into a wait-and-see position — no active hostility, no commitment',
  hostile:     'is now working actively against Nazarick — expect obstruction, intelligence gathering, and quiet aggression',
  war:         'has entered total opposition — coordinated strikes, assassination attempts, and open aggression against Nazarick operatives should be expected'
};

let fired = false;
for (const f of factions) {
  const current = storage[f.standing] ?? 0;
  const prev    = storage[f.threshold] ?? band(current);
  const now     = band(current);
  if (now !== prev) {
    storage[f.threshold] = now;
    if (!fired) {
      effects.push({ type: 'story', instruction: f.name + ' ' + posture[now] + '. Adjust how all ' + f.name + ' NPCs and agents behave this scene and going forward.' });
      fired = true;
    }
  }
}

if (!fired) { skip = true; }

Standing Aid Re-Estize.script:
const tick = check({ type: 'game-tick' });
const last = storage.last_aid_reestize ?? 0;
if (tick - last < 5) {
  skip = true;
} else {
  storage.last_aid_reestize = tick;
  storage.standing_reestize = Math.max(-100, Math.min(100, (storage.standing_reestize ?? 0) + (10)));
}

